/**
 * The TELAS header as the prototype viewer (ESP-11) and the Design stage (ESP-10) read it. Every text of
 * the header is generated by the Designer and untrusted (RNF-05): it is only shown as text.
 */

/** One screen of `TELAS.telas[]`. */
export interface Screen {
  id: string
  name: string
  /** `arquivo` as the header says it, relative to the repository. */
  file: string
  us: string[]
  criteria: string[]
  states: string[]
  operations: string[]
}

/** The parts of the TELAS header the screens use. */
export interface ScreenMap {
  /** `prototipo`, the prototype folder (`docs/design/prototipo/`). */
  prototype: string
  flow: string
  style: string
  screens: Screen[]
  accessibility: { level: string; verified: boolean; notes: string } | undefined
  contractGaps: string[]
}

function text(value: unknown): string {
  return typeof value === 'string' ? value : ''
}

function texts(value: unknown): string[] {
  return Array.isArray(value)
    ? value.filter((item): item is string => typeof item === 'string')
    : []
}

/** ER-11-5: the screens and the screen ↔ story map come from the TELAS header, never from the HTML. */
export function screenMap(header: Record<string, unknown> | undefined): ScreenMap {
  const raw = Array.isArray(header?.telas) ? (header.telas as unknown[]) : []
  const screens = raw.flatMap((item) => {
    if (!item || typeof item !== 'object') return []
    const screen = item as Record<string, unknown>
    const id = text(screen.id)
    if (!id) return []
    return [
      {
        id,
        name: text(screen.nome),
        file: text(screen.arquivo),
        us: texts(screen.us),
        criteria: texts(screen.criterios),
        states: texts(screen.estados),
        operations: texts(screen.operacoes),
      },
    ]
  })
  const a11y = header?.acessibilidade
  const accessibility =
    a11y && typeof a11y === 'object'
      ? {
          level: text((a11y as Record<string, unknown>).nivel),
          verified: (a11y as Record<string, unknown>).verificado === true,
          notes: text((a11y as Record<string, unknown>).observacoes),
        }
      : undefined
  return {
    prototype: text(header?.prototipo),
    flow: text(header?.fluxo),
    style: text(header?.estilo),
    screens,
    accessibility,
    contractGaps: texts(header?.lacunas_contrato),
  }
}

/**
 * The folder the content URL path is relative to: the parent of the prototype folder
 * (`docs/design/` for `docs/design/prototipo/`), as getArtifactContentUrl splits it.
 */
export function contentRoot(prototype: string): string {
  const folder = prototype.replace(/\/+$/, '')
  const slash = folder.lastIndexOf('/')
  return slash < 0 ? '' : folder.slice(0, slash + 1)
}

/** The prototype folder relative to the content root (`prototipo/`). */
export function contentPrefix(prototype: string): string {
  const folder = prototype.replace(/\/+$/, '')
  return folder ? `${folder.slice(contentRoot(prototype).length)}/` : ''
}

/**
 * The `path` of getArtifactContentUrl for a screen file, or undefined when the file is not inside the
 * prototype folder (then the screen has no page to show, ER-11-6).
 */
export function pagePath(prototype: string, file: string): string | undefined {
  const root = contentRoot(prototype)
  const prefix = contentPrefix(prototype)
  if (!prefix || !file.startsWith(root)) return undefined
  const page = file.slice(root.length)
  if (!page.startsWith(prefix) || page.split('/').some((part) => part === '..' || part === '.'))
    return undefined
  return page
}

/** The file shown in the frame bar: relative to `prototipo/` (ESP-11 3, "Caminho"). */
export function displayPath(prototype: string, file: string): string {
  const folder = prototype.endsWith('/') ? prototype : `${prototype}/`
  return file.startsWith(folder) ? file.slice(folder.length) : file
}

/** ER-11-11: the state of a page goes in `?estado=<snake_case>` of the same signed URL. */
export function withState(url: string, state: string | undefined): string {
  if (!state) return url
  const parsed = new URL(url)
  parsed.searchParams.set('estado', state)
  return parsed.toString()
}

/** CA-11-6: "Esta tela atende" — each story with the criteria of it the screen shows. */
export function servedStories(screen: Screen): Array<{ us: string; criteria: string[] }> {
  const stories = screen.us.map((us) => ({ us, criteria: [] as string[] }))
  for (const criterion of screen.criteria) {
    const [us, ca] = criterion.split('/')
    const story = stories.find((item) => item.us === us)
    if (story && ca) story.criteria.push(ca)
  }
  return stories
}

/** Width of the viewer: wide fills the area, narrow is a phone-like column (canvas: 100% / 420px). */
export type ViewerWidth = 'wide' | 'narrow'

/** US-57 CA-1: the point of a click relative to the frame (0 to 1 on both axes, 3 decimals). */
export function relativePoint(
  clientX: number,
  clientY: number,
  box: { left: number; top: number; width: number; height: number },
): { x: number; y: number } {
  const clamp = (value: number) => Math.min(1, Math.max(0, Math.round(value * 1000) / 1000))
  return {
    x: clamp(box.width > 0 ? (clientX - box.left) / box.width : 0),
    y: clamp(box.height > 0 ? (clientY - box.top) / box.height : 0),
  }
}
